// Core tests: the 28 literal core cases from fixtures.json (expected
// values taken verbatim from the file, never generated by the product),
// plus hand-derived boundary, validation, and property cases from the
// SPEC's tests section. Every extra expected value below was computed by
// hand from the SPEC's rules (exact rational arithmetic: energy =
// mAh x V / 1000, usable = energy x DoD / 100, runtime = usable / load,
// half-up rounding once at output, solve capacity ceiled from the
// unrounded exact energy) and cross-checked with Python
// fractions.Fraction before the tests were run.

import assert from "node:assert/strict";
import test from "node:test";
import { formatNumber, run } from "../public/js/core/battery-runtime-calculator.mjs";
import fixtures from "./fixtures.json" with { type: "json" };

const coreCases = fixtures.cases.filter((entry) => entry.kind === "core");
for (const entry of coreCases) {
  test(`fixture ${entry.id}: ${entry.purpose}`, () => {
    assert.deepEqual(run(entry.input), entry.expected);
  });
}

test("fixture count: 28 core and 3 controller cases are vendored", () => {
  assert.equal(coreCases.length, 28);
  assert.equal(fixtures.cases.filter((entry) => entry.kind === "controller").length, 3);
});

const mahBase = { mode: "runtime-mah", capacityMah: "10000", voltage: "3.7", loadWatts: "10" };
const whBase = { mode: "runtime-wh", capacityWh: "100", loadWatts: "10" };

function errorOf(input) {
  const outcome = run(input);
  assert.equal(outcome.ok, false);
  return outcome.error;
}

test("decimal grammar: bare dots, exponents, signs, spaces, commas are DECIMAL_FORMAT", () => {
  for (const capacityMah of [".5", "5.", "1e3", "+5", " 5", "10,000", "５"]) {
    assert.deepEqual(
      errorOf({ ...mahBase, capacityMah }),
      { code: "DECIMAL_FORMAT", field: "capacityMah", row: null },
      `capacityMah ${JSON.stringify(capacityMah)}`,
    );
  }
  for (const loadWatts of [".5", "5.", "1e3", "+5", " 5"]) {
    assert.deepEqual(
      errorOf({ ...whBase, loadWatts }),
      { code: "DECIMAL_FORMAT", field: "loadWatts", row: null },
      `loadWatts ${JSON.stringify(loadWatts)}`,
    );
  }
});

test('leading zeros are legal: "007" is 7 mAh and "00.50" is 0.5% DoD', () => {
  // 7 mAh x 1 V / 1000 = 0.007 Wh -> displays 0.01; 0.007 / 7 W = 0.001 h -> 0.0, 0 min.
  assert.deepEqual(run({ mode: "runtime-mah", capacityMah: "007", voltage: "1", loadWatts: "7" }), {
    ok: true,
    result: {
      mode: "runtime-mah",
      energyWh: 0.01,
      usableWh: 0.01,
      status: "ok",
      runtimeHours: 0,
      runtimeTotalMinutes: 0,
      runtimeHoursPart: 0,
      runtimeMinutesPart: 0,
    },
  });
  // 100 Wh x 0.5% = 0.5 Wh usable; 0.5 / 10 = 0.05 h -> 0.1 h (half-up), 3 min.
  assert.deepEqual(
    run({ mode: "runtime-wh", capacityWh: "100", loadWatts: "10", depthOfDischargePercent: "00.50" }),
    {
      ok: true,
      result: {
        mode: "runtime-wh",
        energyWh: 100,
        usableWh: 0.5,
        status: "ok",
        runtimeHours: 0.1,
        runtimeTotalMinutes: 3,
        runtimeHoursPart: 0,
        runtimeMinutesPart: 3,
      },
    },
  );
});

test("raw limits sit exactly at the legal maximums", () => {
  // depthOfDischargePercent "100.000" is exactly 7 units and legal.
  assert.equal(
    run({ ...whBase, depthOfDischargePercent: "100.000" }).ok,
    true,
  );
  // voltage "1000" and capacityMah "10000000" are legal maximums.
  assert.equal(run({ ...mahBase, voltage: "1000" }).ok, true);
  assert.equal(run({ ...mahBase, capacityMah: "10000000" }).ok, true);
  // voltage "1000.000" is exactly 8 units and legal.
  assert.equal(run({ ...mahBase, voltage: "1000.000" }).ok, true);
  // One unit over the limit is INPUT_LIMIT, before grammar and range.
  assert.deepEqual(errorOf({ ...mahBase, depthOfDischargePercent: "100.0000" }), {
    code: "INPUT_LIMIT",
    field: "depthOfDischargePercent",
    row: null,
  });
  assert.deepEqual(errorOf({ ...whBase, capacityWh: "10000000000" }), {
    code: "INPUT_LIMIT",
    field: "capacityWh",
    row: null,
  });
  assert.deepEqual(errorOf({ ...mahBase, voltage: "1000.0000" }), {
    code: "INPUT_LIMIT",
    field: "voltage",
    row: null,
  });
});

test("ranges: zero capacity and zero voltage are RANGE; legal maximums pass", () => {
  assert.deepEqual(errorOf({ ...mahBase, capacityMah: "0" }), {
    code: "RANGE",
    field: "capacityMah",
    row: null,
  });
  assert.deepEqual(errorOf({ ...mahBase, capacityMah: "10000001" }), {
    code: "RANGE",
    field: "capacityMah",
    row: null,
  });
  assert.deepEqual(errorOf({ ...mahBase, voltage: "0" }), {
    code: "RANGE",
    field: "voltage",
    row: null,
  });
  assert.deepEqual(errorOf({ ...whBase, capacityWh: "100001" }), {
    code: "RANGE",
    field: "capacityWh",
    row: null,
  });
  assert.deepEqual(errorOf({ ...whBase, loadWatts: "1000001" }), {
    code: "RANGE",
    field: "loadWatts",
    row: null,
  });
  assert.deepEqual(errorOf({ ...whBase, depthOfDischargePercent: "100.1" }), {
    code: "RANGE",
    field: "depthOfDischargePercent",
    row: null,
  });
  assert.equal(run({ ...whBase, loadWatts: "0" }).ok, true);
  assert.equal(run({ ...whBase, loadWatts: "1000000" }).ok, true);
});

test('seriesCount "0" is RANGE; 1 and 100 pass; 101 is RANGE', () => {
  const packBase = {
    mode: "pack",
    cellCapacityMah: "3500",
    cellVoltage: "3.7",
    seriesCount: "4",
    parallelCount: "2",
    loadWatts: "10",
  };
  assert.deepEqual(errorOf({ ...packBase, seriesCount: "0" }), {
    code: "RANGE",
    field: "seriesCount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...packBase, parallelCount: "0" }), {
    code: "RANGE",
    field: "parallelCount",
    row: null,
  });
  assert.deepEqual(errorOf({ ...packBase, seriesCount: "101" }), {
    code: "RANGE",
    field: "seriesCount",
    row: null,
  });
  assert.equal(run({ ...packBase, seriesCount: "1", parallelCount: "100" }).ok, true);
  assert.equal(run({ ...packBase, seriesCount: "100", parallelCount: "1" }).ok, true);
});

test("a lone surrogate is UNICODE, after capacity and before grammar", () => {
  assert.deepEqual(errorOf({ ...mahBase, capacityMah: "5\uD800" }), {
    code: "UNICODE",
    field: "capacityMah",
    row: null,
  });
  assert.deepEqual(errorOf({ ...whBase, loadWatts: "\uDC00" }), {
    code: "UNICODE",
    field: "loadWatts",
    row: null,
  });
});

test("the first field in the mode's fixed order reports first", () => {
  // runtime-mah order: capacityMah, voltage, loadWatts, DoD.
  assert.deepEqual(errorOf({ ...mahBase, capacityMah: "x", voltage: "x" }), {
    code: "DECIMAL_FORMAT",
    field: "capacityMah",
    row: null,
  });
  assert.deepEqual(errorOf({ ...mahBase, voltage: "x", loadWatts: "x" }), {
    code: "DECIMAL_FORMAT",
    field: "voltage",
    row: null,
  });
  // runtime-wh order: capacityWh, loadWatts, DoD.
  assert.deepEqual(errorOf({ ...whBase, capacityWh: "x", loadWatts: "x" }), {
    code: "DECIMAL_FORMAT",
    field: "capacityWh",
    row: null,
  });
  // pack order: cellCapacityMah, cellVoltage, seriesCount, parallelCount, loadWatts, DoD.
  const packBad = {
    mode: "pack",
    cellCapacityMah: "3500",
    cellVoltage: "3.7",
    seriesCount: "2.5",
    parallelCount: "x",
    loadWatts: "10",
  };
  assert.deepEqual(errorOf(packBad), {
    code: "INTEGER_FORMAT",
    field: "seriesCount",
    row: null,
  });
  // solve order: targetRuntimeHours, loadWatts, voltage, DoD.
  assert.deepEqual(
    errorOf({ mode: "solve", targetRuntimeHours: "x", loadWatts: "x", voltage: "x" }),
    { code: "DECIMAL_FORMAT", field: "targetRuntimeHours", row: null },
  );
});

test("validation order across steps: ENUM before field-set, field-set before type", () => {
  // Unknown mode with an extra field still reports ENUM (step 2 before step 3).
  assert.deepEqual(errorOf({ mode: "turbo", extra: "1" }), {
    code: "ENUM",
    field: "mode",
    row: null,
  });
  // An inapplicable field reports SCHEMA even when another value is non-string (step 3 before step 4).
  assert.deepEqual(errorOf({ ...whBase, voltage: "3.7", loadWatts: 10 }), {
    code: "SCHEMA",
    field: null,
    row: null,
  });
});

test("schema: missing mode, non-string mode, missing required field, wrong type, array, null, accessor are SCHEMA", () => {
  const schema = { code: "SCHEMA", field: null, row: null };
  assert.deepEqual(errorOf({ capacityMah: "10000", voltage: "3.7", loadWatts: "10" }), schema);
  assert.deepEqual(errorOf({ ...mahBase, mode: 7 }), schema);
  const missing = { ...mahBase };
  delete missing.voltage;
  assert.deepEqual(errorOf(missing), schema);
  assert.deepEqual(errorOf({ ...mahBase, capacityMah: 10000 }), schema);
  assert.deepEqual(errorOf(["runtime-mah"]), schema);
  assert.deepEqual(errorOf(null), schema);
  assert.deepEqual(errorOf("runtime-mah"), schema);
  const withGetter = { ...mahBase };
  Object.defineProperty(withGetter, "voltage", {
    enumerable: true,
    get() {
      return "3.7";
    },
  });
  assert.deepEqual(errorOf(withGetter), schema);
  // An empty-string DoD is EMPTY, not absent.
  assert.deepEqual(errorOf({ ...whBase, depthOfDischargePercent: "" }), {
    code: "EMPTY",
    field: "depthOfDischargePercent",
    row: null,
  });
  // An absent DoD is 100%: same result as an explicit "100".
  assert.deepEqual(run(whBase), run({ ...whBase, depthOfDischargePercent: "100" }));
});

test("half-up tie on displayed energy: 12.345 Wh displays 12.35, runtime from the exact value", () => {
  // 12345 mAh x 1 V / 1000 = 12.345 Wh exactly; 12.345 / 1 W = 12.345 h
  // -> 12.3 h (1 dp half-up), 740.7 min -> 741 min = 12 h 21 min.
  assert.deepEqual(run({ mode: "runtime-mah", capacityMah: "12345", voltage: "1", loadWatts: "1" }), {
    ok: true,
    result: {
      mode: "runtime-mah",
      energyWh: 12.35,
      usableWh: 12.35,
      status: "ok",
      runtimeHours: 12.3,
      runtimeTotalMinutes: 741,
      runtimeHoursPart: 12,
      runtimeMinutesPart: 21,
    },
  });
});

test("solve capacity is ceiled from the unrounded exact energy, not the displayed value", () => {
  // 3 W x 1 h at 3.7 V with DoD 100%: exact 3 Wh -> 3 / 3.7 x 1000
  // = 810.8108... mAh -> ceil 811. Displayed energy 3 Wh agrees here,
  // but the ceiling comes from the exact fraction.
  assert.deepEqual(
    run({ mode: "solve", targetRuntimeHours: "1", loadWatts: "3", voltage: "3.7" }),
    {
      ok: true,
      result: { mode: "solve", status: "ok", requiredEnergyWh: 3, requiredCapacityMah: 811 },
    },
  );
  // With DoD 33.333%: exact energy = 3 / 0.33333 = 9.00009 Wh -> 9.0;
  // capacity = 9.00009 / 3.7 x 1000 = 2432.456... -> 2433.
  assert.deepEqual(
    run({
      mode: "solve",
      targetRuntimeHours: "1",
      loadWatts: "3",
      voltage: "3.7",
      depthOfDischargePercent: "33.333",
    }),
    {
      ok: true,
      result: { mode: "solve", status: "ok", requiredEnergyWh: 9, requiredCapacityMah: 2433 },
    },
  );
});

test("property over every successful fixture: minutes part is 0-59 and splits the single total", () => {
  for (const entry of coreCases) {
    if (!entry.expected.ok || entry.expected.result.mode === "solve") continue;
    const outcome = run(entry.input);
    assert.equal(outcome.ok, true, entry.id);
    const r = outcome.result;
    if (r.status === "infinite") {
      assert.equal(r.runtimeTotalMinutes, null, entry.id);
      assert.equal(r.runtimeHours, null, entry.id);
      continue;
    }
    assert.ok(r.runtimeMinutesPart >= 0 && r.runtimeMinutesPart <= 59, entry.id);
    assert.equal(
      r.runtimeHoursPart * 60 + r.runtimeMinutesPart,
      r.runtimeTotalMinutes,
      entry.id,
    );
  }
});

test("property: pack energy equals cell Wh x series x parallel (the SPEC invariant)", () => {
  const packs = [
    { cellCapacityMah: "3500", cellVoltage: "3.7", seriesCount: "4", parallelCount: "2", loadWatts: "37" },
    { cellCapacityMah: "2600.5", cellVoltage: "3.65", seriesCount: "3", parallelCount: "5", loadWatts: "10" },
    { cellCapacityMah: "10000000", cellVoltage: "1000", seriesCount: "100", parallelCount: "100", loadWatts: "1" },
  ];
  for (const pack of packs) {
    const outcome = run({ mode: "pack", ...pack });
    assert.equal(outcome.ok, true);
    const { packCapacityMah, packVoltageV, energyWh } = outcome.result;
    // Exact decimal check in micro-units with BigInt, avoiding binary
    // floats: energy = packCapacityMah x packVoltageV / 1000, then the
    // displayed energyWh is that exact value rounded half-up to 2 dp.
    const capMicro = BigInt(Math.round(packCapacityMah * 1000000));
    const voltMicro = BigInt(Math.round(packVoltageV * 1000000));
    const energyMicro = (capMicro * voltMicro) / 1000000000n;
    const displayedMicro = ((energyMicro * 2n + 10000n) / 20000n) * 10000n;
    assert.equal(displayedMicro, BigInt(Math.round(energyWh * 1000000)));
  }
});

test("property: solve capacity never falls short and never overshoots by a full mAh", () => {
  // Independent integer recomputation: requiredEnergyExact as a
  // fraction, then the ceiling is checked from both sides.
  const cases = [
    { targetRuntimeHours: "10", loadWatts: "5", voltage: "3.7" },
    { targetRuntimeHours: "8", loadWatts: "25", voltage: "12", depthOfDischargePercent: "50" },
    { targetRuntimeHours: "1", loadWatts: "3", voltage: "3.7", depthOfDischargePercent: "33.333" },
    { targetRuntimeHours: "100000", loadWatts: "1000000", voltage: "1000" },
  ];
  for (const solve of cases) {
    const outcome = run({ mode: "solve", ...solve });
    assert.equal(outcome.ok, true);
    const dodMicro = solve.depthOfDischargePercent
      ? BigInt(Math.round(Number(solve.depthOfDischargePercent) * 1000000))
      : 100000000n;
    const loadMicro = BigInt(Math.round(Number(solve.loadWatts) * 1000000));
    const targetMicro = BigInt(Math.round(Number(solve.targetRuntimeHours) * 1000000));
    const voltMicro = BigInt(Math.round(Number(solve.voltage) * 1000000));
    // requiredEnergyExact = load x target x 100 / dod, as n/d.
    const n = loadMicro * targetMicro * 100n;
    const d = 1000000n * dodMicro;
    // capacity fraction = requiredEnergyExact / voltage x 1000 = n x 10^9 / (d x voltMicro).
    const capN = n * 1000000000n;
    const capD = d * voltMicro;
    const cap = BigInt(outcome.result.requiredCapacityMah);
    // cap-1 < fraction <= cap (with cap = 0 only when the fraction is 0).
    assert.ok(cap === 0n ? capN === 0n : (cap - 1n) * capD < capN, JSON.stringify(solve));
    assert.ok(cap * capD >= capN, JSON.stringify(solve));
  }
});

test("display formatting: fixed decimals, no thousands separators", () => {
  assert.equal(formatNumber(0, 2), "0.00");
  assert.equal(formatNumber(3.7, 1), "3.7");
  assert.equal(formatNumber(12.35, 2), "12.35");
  assert.equal(formatNumber(100000, 2), "100000.00");
});
